import itertools, math, time, sys, random

# Let's try to see if there's a known solution or use a SAT solver.

# We can try using python's built-in solvers. Let's try pysat or z3.

# First, let's check if pysat is available.
try:
    import pysat
    print("pysat available")
except:
    print("pysat not available")

try:
    import z3
    print("z3 available")
except:
    print("z3 not available")

try:
    import pycosat
    print("pycosat available")
except:
    print("pycosat not available")

import z3

# Parameters
NUM_GOLFERS = 40
WEEKS = 5
GROUPS_PER_WEEK = 10
GROUP_SIZE = 4

# Create solver
solver = z3.Solver()

# Decision variables: x[w][g][p] = 1 if golfer p is in group g in week w
x = [[[z3.Bool(f'x_{w}_{g}_{p}') for p in range(NUM_GOLFERS)] 
      for g in range(GROUPS_PER_WEEK)] 
     for w in range(WEEKS)]

# Each golfer in exactly one group per week
for w in range(WEEKS):
    for p in range(NUM_GOLFERS):
        solver.add(z3.PbEq([(x[w][g][p], 1) for g in range(GROUPS_PER_WEEK)], 1))

# Each group has exactly GROUP_SIZE golfers
for w in range(WEEKS):
    for g in range(GROUPS_PER_WEEK):
        solver.add(z3.PbEq([(x[w][g][p], 1) for p in range(NUM_GOLFERS)], GROUP_SIZE))

# No pair of golfers meets more than once
for p1 in range(NUM_GOLFERS):
    for p2 in range(p1+1, NUM_GOLFERS):
        together_week = [z3.Bool(f'together_{p1}_{p2}_w{w}') for w in range(WEEKS)]
        for w in range(WEEKS):
            solver.add(z3.Implies(together_week[w], 
                                  z3.Or([z3.And(x[w][g][p1], x[w][g][p2]) for g in range(GROUPS_PER_WEEK)])))
            solver.add(z3.Implies(z3.Or([z3.And(x[w][g][p1], x[w][g][p2]) for g in range(GROUPS_PER_WEEK)]),
                                  together_week[w]))
        solver.add(z3.PbLe([(together_week[w], 1) for w in range(WEEKS)], 1))

print("Solving...")
result = solver.check()
print(result)

if result == z3.sat:
    model = solver.model()
    # Extract solution
    solution = [0] * (WEEKS * NUM_GOLFERS)
    for w in range(WEEKS):
        for p in range(NUM_GOLFERS):
            for g in range(GROUPS_PER_WEEK):
                if z3.is_true(model[x[w][g][p]]):
                    solution[w * NUM_GOLFERS + p] = g
                    break
    print(solution)

    # Verify
    # Check each week: each golfer in exactly one group
    for w in range(WEEKS):
        groups = [[] for _ in range(GROUPS_PER_WEEK)]
        for p in range(NUM_GOLFERS):
            g = solution[w * NUM_GOLFERS + p]
            groups[g].append(p)
        for g in range(GROUPS_PER_WEEK):
            assert len(groups[g]) == GROUP_SIZE, f"Week {w}, group {g} has {len(groups[g])} golfers"

    # Check no pair meets twice
    pair_weeks = {}
    for w in range(WEEKS):
        groups = [[] for _ in range(GROUPS_PER_WEEK)]
        for p in range(NUM_GOLFERS):
            g = solution[w * NUM_GOLFERS + p]
            groups[g].append(p)
        for g in range(GROUPS_PER_WEEK):
            for i in range(GROUP_SIZE):
                for j in range(i+1, GROUP_SIZE):
                    p1, p2 = groups[g][i], groups[g][j]
                    key = (min(p1, p2), max(p1, p2))
                    if key in pair_weeks:
                        print(f"ERROR: Pair {key} meets in weeks {pair_weeks[key]} and {w}")
                    pair_weeks[key] = w
    print(f"Total pairs: {len(pair_weeks)}")
    print("Verification passed!")
